CREATE VIEW [dbo].[ApparecchiIncassi2] AS SELECT 'NSL' AS Categoria, 'New Slot' AS Tipo, incassi.codicelocale AS IdLocale,2 AS TipoOggetto,'NSL' AS TipoOggettoDesc,incassi.CodiceOggetto,incassi.prop AS Proprieta,incassi.agente, incassi.Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 1 AS TM ,NULL AS idmove, incassi.idincasso,incassi.data, tipoincasso, incassi.incasso,incassonetto, ricevuta, contatore1, contatore2, contatore3, contatore4, bollettaincasso, trasferito, totaleentrate, totaleuscite, perc, tasse, aams, rete, idmagazzino, 0 AS Ordinamento, 0 AS OrdinamentoCategoria,idconcessionario,societa.ragionesociale,tipomerce AS TipoScarto,locali.Nome as Locale  FROM incassi,dedicati,societa,locali WHERE locali.idlocale=incassi.codicelocale AND societa.idsocieta=incassi.prop AND dedicati.iddedicato=incassi.codiceoggetto AND incassi.partipologiamonopoli=1 AND incassi.tipooggetto=2 UNION SELECT 'C7A' AS Categoria, 'Gioco' AS Tipo, incassi.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,incassi.CodiceOggetto,incassi.prop AS Proprieta,incassi.agente, incassi.Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 2 AS TM, NULL AS idmove, incassi.idincasso, incassi.data, tipoincasso, incassi.incasso,incassonetto, ricevuta, contatore1, contatore2, contatore3, contatore4, bollettaincasso, trasferito, totaleentrate, totaleuscite, perc, tasse, aams, rete, idmagazzino, 0 AS Ordinamento, 1 AS OrdinamentoCategoria,idconcessionario,societa.ragionesociale,tipomerce AS TipoScarto,locali.Nome as Locale   FROM incassi,dedicati,societa,locali WHERE locali.idlocale=incassi.codicelocale AND societa.idsocieta=incassi.prop AND dedicati.iddedicato=incassi.codiceoggetto AND incassi.partipologiamonopoli=2  AND incassi.tipooggetto=2 UNION SELECT 'C7C' AS Categoria, 'Gioco' AS Tipo, incassi.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,incassi.CodiceOggetto,incassi.prop AS Proprieta,incassi.agente, incassi.Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, 4 AS TM, NULL AS idmove, incassi.idincasso, incassi.data, tipoincasso, incassi.incasso,incassonetto, ricevuta, contatore1, contatore2, contatore3, contatore4, bollettaincasso, trasferito, totaleentrate, totaleuscite, perc, tasse, aams, rete, idmagazzino, 0 AS Ordinamento, 2 AS OrdinamentoCategoria,idconcessionario,societa.ragionesociale,tipomerce AS TipoScarto,locali.Nome as Locale   FROM incassi,dedicati,societa,locali WHERE locali.idlocale=incassi.codicelocale AND societa.idsocieta=incassi.prop AND dedicati.iddedicato=incassi.codiceoggetto AND incassi.partipologiamonopoli=4  AND incassi.tipooggetto=2 UNION SELECT 'MEC' AS Categoria, 'Gioco' AS Tipo, incassi.codicelocale AS IdLocale,2 AS TipoOggetto,'GIO' AS TipoOggettoDesc,incassi.CodiceOggetto,incassi.prop AS Proprieta,incassi.agente, incassi.Associato, dedicati.matricola,dedicati.nome as Modello, dedicati.identificativo,dedicati.nullaosta, NULL AS TM, NULL AS idmove, incassi.idincasso, incassi.data, tipoincasso, incassi.incasso,incassonetto, ricevuta, contatore1, contatore2, contatore3, contatore4, bollettaincasso, trasferito, totaleentrate, totaleuscite, perc, tasse, aams, rete, idmagazzino, 0 AS Ordinamento, 3 AS OrdinamentoCategoria,idconcessionario,societa.ragionesociale,tipomerce AS TipoScarto,locali.Nome as Locale   FROM incassi,dedicati,societa,locali WHERE locali.idlocale=incassi.codicelocale AND societa.idsocieta=incassi.prop AND dedicati.iddedicato=incassi.codiceoggetto AND (incassi.partipologiamonopoli>4 OR incassi.partipologiamonopoli IS NULL)  AND incassi.tipooggetto=2 UNION SELECT 'SCH' AS Categoria, 'Scheda' AS Tipo, incassi.codicelocale AS IdLocale,1 AS TipoOggetto,'SCH' AS TipoOggettoDesc, incassi.CodiceOggetto,incassi.prop AS Proprieta,incassi.agente, incassi.Associato, schede.matricola,schede.nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM, NULL AS idmove, incassi.idincasso, incassi.data, tipoincasso, incassi.incasso,incassonetto, ricevuta, contatore1, contatore2, contatore3, contatore4, bollettaincasso, trasferito, totaleentrate, totaleuscite, perc, tasse, aams, rete, idmagazzino, 3 AS Ordinamento, 0 AS OrdinamentoCategoria,NULL AS idconcessionario,societa.ragionesociale,tipomerce AS TipoScarto,locali.Nome as Locale   FROM incassi ,schede,societa,locali WHERE locali.idlocale=incassi.codicelocale AND societa.idsocieta=incassi.prop AND schede.idscheda=incassi.codiceoggetto AND  incassi.tipooggetto=1 UNION SELECT 'DIS' AS Categoria, 'Distributore' AS Tipo, incassi.codicelocale AS IdLocale,15 AS TipoOggetto,'DIS' AS TipoOggettoDesc, incassi.CodiceOggetto,incassi.prop AS Proprieta,incassi.agente, incassi.Associato, distribut.matricola,distribut.nome as Modello, '' AS identificativo,'' AS nullaosta, NULL AS TM, NULL AS idmove, incassi.idincasso, incassi.data, tipoincasso, incassi.incasso,incassonetto, ricevuta, contatore1, contatore2, contatore3, contatore4, bollettaincasso, trasferito, totaleentrate, totaleuscite, perc, tasse, aams, rete, idmagazzino, 4 AS Ordinamento, 0 AS OrdinamentoCategoria,NULL AS idconcessionario,societa.ragionesociale,tipomerce AS TipoScarto,locali.Nome as Locale  FROM incassi,distribut,societa,locali WHERE locali.idlocale=incassi.codicelocale AND societa.idsocieta=incassi.prop AND distribut.iddistributore=incassi.codiceoggetto AND  incassi.tipooggetto=15
GO
